def is_noise(grid, i, j):
    """True if cell (i, j) has no same-color cell in its 8-neighborhood (an isolated stray pixel)."""
    h, w = len(grid), len(grid[0])
    return not any(grid[i][j] == grid[i+di][j+dj] for di in (-1, 0, 1) for dj in (-1, 0, 1)
                   if (di or dj) and 0 <= i+di < h and 0 <= j+dj < w)

def noise_cells(grid):
    """All isolated stray pixels of the grid, as a set of (i, j)."""
    h, w = len(grid), len(grid[0])
    return {(i, j) for i in range(h) for j in range(w) if is_noise(grid, i, j)}

def solid_rectangles(grid, noise):
    """Bounding boxes of connected same-color components (>=2 cells) whose box holds only that color or noise; (top, bottom, left, right, area, color)."""
    h, w = len(grid), len(grid[0])
    rects = []
    for c in set(v for row in grid for v in row):
        seen = set()
        for i0 in range(h):
            for j0 in range(w):
                if grid[i0][j0] != c or (i0, j0) in seen:
                    continue
