                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p = (y+dy, x+dx)
                        if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == c and p not in comp:
                            comp.add(p); st.append(p)
                seen |= comp
                if len(comp) < 2:
                    continue
                ys = [y for y, x in comp]; xs = [x for y, x in comp]
                t, b, l, r = min(ys), max(ys), min(xs), max(xs)
                if all(grid[y][x] == c or (y, x) in noise for y in range(t, b+1) for x in range(l, r+1)):
                    rects.append((t, b, l, r, (b-t+1)*(r-l+1), c))
    return rects

def background_color(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def fill_noise(grid):
    """Replace every isolated stray pixel: by the color of the smallest solid rectangle containing it, else the background color."""
    g = [row[:] for row in grid]
    noise = noise_cells(g)
    rects = solid_rectangles(g, noise)
    bg = background_color(g)
    for (i, j) in sorted(noise):
        cs = [rc for rc in rects if rc[0] <= i <= rc[1] and rc[2] <= j <= rc[3]]
        g[i][j] = min(cs)[5] if cs else bg
    return g
